### Step 8: Orchestration in build_findings

In `src/tools/review.rs`, modify `build_findings` (lines ~246-294):

```rust
if !all_sym_attrs.is_empty() {
    // Build file -> component_id map
    let comp_with_paths = db.active_components_with_paths()?;
    let mut file_to_component: HashMap<String, String> = HashMap::new();
    for (comp_id, _name, paths) in &comp_with_paths {
        for path in paths {
            file_to_component.insert(path.clone(), comp_id.clone());
        }
    }

    // Tag each SymbolAttrs with its component
    for sa in &mut all_sym_attrs {
        sa.component_id = file_to_component.get(&sa.file).cloned();
    }

    // 1. Global FCA (all symbols, MIN_SUPPORT=3)
    let mut global_engine = FcaEngine::new();
    let global_conventions = global_engine.rebuild(&all_sym_attrs);

    // 2. Per-component FCA
    let mut all_conventions = global_conventions.clone();
    for (comp_id, _name, paths) in &comp_with_paths {
        let path_set: HashSet<&str> = paths.iter().map(|p| p.as_str()).collect();
        let comp_symbols: Vec<_> = all_sym_attrs
            .iter()
            .filter(|s| path_set.contains(s.file.as_str()))
            .cloned()
            .collect();
        if comp_symbols.len() < 2 {
            continue;
        }
        let min_support = std::cmp::max(2, (comp_symbols.len() as f64 * 0.4).ceil() as usize);
        let mut comp_engine = FcaEngine::new();
        let comp_convs = comp_engine.rebuild_with_params(
            &comp_symbols, min_support, MIN_CONFIDENCE, Some(comp_id),
        );
        let deduped = deduplicate_component_conventions(comp_convs, &global_conventions);
        all_conventions.extend(deduped);
    }

    // 3. Persist to DB
    for c in &all_conventions {
        let _ = db.upsert_convention(
            &c.id,
            &c.antecedent.join(", "),
            &c.consequent.join(", "),
            c.support as i64,
            c.confidence,
            c.component_id.as_deref(),
        );
    }
    let current_ids: Vec<&str> = all_conventions.iter().map(|c| c.id.as_str()).collect();
    let _ = db.delete_stale_conventions(&current_ids);

    // 4. Check (scoped)
    // Build a temporary engine with all conventions for check
    let mut check_engine = FcaEngine::new();
    check_engine.set_conventions(all_conventions);  // new setter method

    // ... existing forbidden/suppress logic unchanged ...

    for v in check_engine.check(&changed_sym_attrs, &effective_conventions) {
        convention_violations.push(ConventionViolation { ... });
    }
}
```

Note: need to add `FcaEngine::set_conventions(convs: Vec<Convention>)` — a simple setter to inject conventions for check without running FCA. Also need to export `MIN_CONFIDENCE` and `deduplicate_component_conventions` from the conventions module.

### Step 9: Tests

Add tests in `src/conventions/engine.rs` test module:

**Adaptive threshold test** — verify small component (5 symbols) uses min_support=2, large component (50 symbols) uses min_support=20:

```rust
#[test]
fn adaptive_threshold_small_component() {
    // 5 symbols, 4 sharing an attribute pattern → min_support=max(2, ceil(5*0.4))=2
    let symbols = make_small_component_symbols(5);
    let mut engine = FcaEngine::new();
    let convs = engine.rebuild_with_params(&symbols, 2, MIN_CONFIDENCE, Some("comp-1"));
    assert!(!convs.is_empty());
    assert!(convs.iter().all(|c| c.component_id.as_deref() == Some("comp-1")));
}

#[test]
fn adaptive_threshold_large_component() {
    // 50 symbols, need min_support=20 → only strong patterns survive
    let symbols = make_large_component_symbols(50);
    let mut engine = FcaEngine::new();
    let convs_high = engine.rebuild_with_params(&symbols, 20, MIN_CONFIDENCE, Some("comp-2"));
    let mut engine2 = FcaEngine::new();
    let convs_low = engine2.rebuild_with_params(&symbols, 2, MIN_CONFIDENCE, Some("comp-2"));
    assert!(convs_high.len() <= convs_low.len());
}
```

