**Scoped check test** — symbol in component A is checked against global + A's conventions, not B's:

```rust
#[test]
fn check_scoped_to_symbol_component() {
    let mut engine = FcaEngine::new();
    engine.set_conventions(vec![
        // Global convention
        Convention { component_id: None, ... },
        // Component A convention
        Convention { component_id: Some("a".into()), ... },
        // Component B convention
        Convention { component_id: Some("b".into()), ... },
    ]);
    let sym_in_a = SymbolAttrs { component_id: Some("a".into()), ... };
    let violations = engine.check(&[sym_in_a], &ConventionsConfig::default());
    // Should see violations from global + A, never from B
}

